<?php
declare(strict_types=1);use Alprof\Services\FinanceService;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use Dompdf\Dompdf;require dirname(__DIR__).'/app/bootstrap.php';
global $db,$auth;
$auth->requireAuth();if(!$auth->can('reports.export')){http_response_code(403);exit;}$g=(int)($_GET['group_id']??0);$m=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$m))$m=date('Y-m');$svc=new FinanceService($db);$rows=$svc->rows($g,$m.'-01');$format=$_GET['format']??'xlsx';
if($format==='xlsx'){if(!class_exists(Spreadsheet::class)){http_response_code(500);exit('نفذ composer install');}$x=new Spreadsheet();$w=$x->getActiveSheet();$w->setRightToLeft(true);$w->fromArray(['اسم الطالب','المقرر','المسدد','المتبقي','الحالة','تاريخ السداد'],null,'A1');$i=2;foreach($rows as $r){$w->fromArray([$r['name'],$r['assessed'],$r['paid'],$r['remaining'],$r['status'],$r['paid_date']],null,'A'.$i++);}foreach(range('A','F')as$c)$w->getColumnDimension($c)->setAutoSize(true);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="finance-'.$m.'.xlsx"');(new Xlsx($x))->save('php://output');exit;}
if(!class_exists(Dompdf::class)){http_response_code(500);exit('نفذ composer install');}$html='<html dir="rtl"><meta charset="utf-8"><style>body{font-family:DejaVu Sans}table{width:100%;border-collapse:collapse}th{background:#25345f;color:white}th,td{padding:8px;border:1px solid #ddd}</style><h1>منصة البروف التعليمية — تقرير الماليات '.$m.'</h1><table><tr><th>الطالب</th><th>المقرر</th><th>المسدد</th><th>المتبقي</th><th>الحالة</th></tr>';foreach($rows as $r)$html.='<tr><td>'.htmlspecialchars($r['name']).'</td><td>'.$r['assessed'].'</td><td>'.$r['paid'].'</td><td>'.$r['remaining'].'</td><td>'.htmlspecialchars($r['status']).'</td></tr>';$html.='</table></html>';$pdf=new Dompdf();$pdf->loadHtml($html,'UTF-8');$pdf->setPaper('A4','landscape');$pdf->render();$pdf->stream('finance-'.$m.'.pdf',['Attachment'=>true]);
